package com.hsib.sib.data

import android.content.Context
import android.os.Build
import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import java.io.File
import java.security.KeyStore
import java.security.SecureRandom
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

/**
 * Wraps small secrets with a non-exportable AES-GCM key held by the Android Keystore (hardware backed, and in
 * StrongBox where the phone has it). The random IV is generated by the keystore, so the app never chooses a nonce.
 */
class KeystoreBox(private val alias: String) {
    private fun key(): SecretKey {
        val ks = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
        (ks.getKey(alias, null) as? SecretKey)?.let { return it }
        fun spec(strongBox: Boolean) = KeyGenParameterSpec.Builder(alias, KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT)
            .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
            .setKeySize(256)
            .setRandomizedEncryptionRequired(true)
            .apply { if (strongBox && Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) setIsStrongBoxBacked(true) }
            .build()
        val gen = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore")
        // StrongBox exists from Android 9 and only on some phones; any failure falls back to the normal secure hardware.
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            try {
                gen.init(spec(true))
                return gen.generateKey()
            } catch (_: Exception) {
                // No StrongBox on this phone.
            }
        }
        gen.init(spec(false))
        return gen.generateKey()
    }

    fun seal(plain: ByteArray, aad: ByteArray): ByteArray {
        val c = Cipher.getInstance("AES/GCM/NoPadding")
        c.init(Cipher.ENCRYPT_MODE, key())
        c.updateAAD(aad)
        val ct = c.doFinal(plain)
        val iv = c.iv
        return byteArrayOf(1, iv.size.toByte()) + iv + ct
    }

    /** Returns null when the key is gone or the data was altered. */
    fun open(blob: ByteArray, aad: ByteArray): ByteArray? = try {
        require(blob.size > 2 && blob[0].toInt() == 1)
        val ivLen = blob[1].toInt()
        val iv = blob.copyOfRange(2, 2 + ivLen)
        val c = Cipher.getInstance("AES/GCM/NoPadding")
        c.init(Cipher.DECRYPT_MODE, key(), GCMParameterSpec(128, iv))
        c.updateAAD(aad)
        c.doFinal(blob, 2 + ivLen, blob.size - 2 - ivLen)
    } catch (_: Exception) {
        null
    }

    fun delete() {
        runCatching { KeyStore.getInstance("AndroidKeyStore").apply { load(null) }.deleteEntry(alias) }
    }
}

/** The vault master key: 256 random bits, only ever stored wrapped by the device key. */
class Vault(private val context: Context) {
    sealed interface State {
        class Ready(val master: ByteArray) : State
        data object Lost : State
    }

    private val box = KeystoreBox("sib_device_key_v1")
    private val file get() = File(context.filesDir, "vault.bin")
    private val aad = "sib-vault-v1".toByteArray()

    fun open(): State {
        if (!file.exists()) {
            // A database without its key is unreadable: that is a lost vault, not a fresh install.
            if (context.getDatabasePath(DB_NAME).exists()) return State.Lost
            val master = ByteArray(32).also { SecureRandom().nextBytes(it) }
            file.writeBytes(box.seal(master, aad))
            return State.Ready(master)
        }
        val master = box.open(file.readBytes(), aad) ?: return State.Lost
        return State.Ready(master)
    }

    /** Throws away the lost vault and its database so the app can start clean (the user chose this). */
    fun reset() {
        file.delete()
        box.delete()
        listOf(DB_NAME, "$DB_NAME-wal", "$DB_NAME-shm", "$DB_NAME-journal").forEach { context.getDatabasePath(it).delete() }
        File(context.filesDir, "receipts").deleteRecursively()
        File(context.filesDir, "backup_key.bin").delete()
    }

    companion object {
        const val DB_NAME = "sib.db"
    }
}
